--
-- Table structure for table `sales_order_onlines`
--

DROP TABLE IF EXISTS `sales_order_onlines`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sales_order_onlines` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `store_id` bigint unsigned NOT NULL,
  `online_shop_provider_id` bigint unsigned NOT NULL,
  `delivery_service_id` bigint unsigned NOT NULL,
  `date` date NOT NULL,
  `customer_id` bigint unsigned DEFAULT NULL,
  `delivery_address_id` bigint unsigned DEFAULT NULL,
  `receipt_no` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` tinyint NOT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_by_id` bigint unsigned DEFAULT NULL,
  `approved_by_id` bigint unsigned DEFAULT NULL,
  `image_sent` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `sales_order_onlines_approved_by_id_foreign` (`approved_by_id`),
  KEY `sales_order_onlines_created_by_id_foreign` (`created_by_id`),
  KEY `sales_order_onlines_customer_id_foreign` (`customer_id`),
  KEY `sales_order_onlines_delivery_address_id_foreign` (`delivery_address_id`),
  KEY `sales_order_onlines_delivery_service_id_foreign` (`delivery_service_id`),
  KEY `sales_order_onlines_online_shop_provider_id_foreign` (`online_shop_provider_id`),
  KEY `sales_order_onlines_store_id_foreign` (`store_id`),
  CONSTRAINT `sales_order_onlines_approved_by_id_foreign` FOREIGN KEY (`approved_by_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `sales_order_onlines_created_by_id_foreign` FOREIGN KEY (`created_by_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `sales_order_onlines_customer_id_foreign` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `sales_order_onlines_delivery_address_id_foreign` FOREIGN KEY (`delivery_address_id`) REFERENCES `delivery_addresses` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `sales_order_onlines_delivery_service_id_foreign` FOREIGN KEY (`delivery_service_id`) REFERENCES `delivery_services` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `sales_order_onlines_online_shop_provider_id_foreign` FOREIGN KEY (`online_shop_provider_id`) REFERENCES `online_shop_providers` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `sales_order_onlines_store_id_foreign` FOREIGN KEY (`store_id`) REFERENCES `stores` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11265 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

