--
-- Table structure for table `sales_order_directs`
--

DROP TABLE IF EXISTS `sales_order_directs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sales_order_directs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `delivery_date` date NOT NULL,
  `delivery_location_id` bigint unsigned DEFAULT NULL,
  `delivery_service_id` bigint unsigned NOT NULL,
  `transfer_to_account_id` bigint unsigned NOT NULL,
  `image_transfer` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payment_status` tinyint NOT NULL,
  `delivery_status` tinyint NOT NULL,
  `shipping_cost` bigint DEFAULT NULL,
  `store_id` bigint unsigned DEFAULT NULL,
  `image_receipt` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `submitted_by_id` bigint unsigned DEFAULT NULL,
  `received_by` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sign` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `order_by_id` bigint unsigned DEFAULT NULL,
  `discounts` bigint DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `sales_order_directs_delivery_location_id_foreign` (`delivery_location_id`),
  KEY `sales_order_directs_delivery_service_id_foreign` (`delivery_service_id`),
  KEY `sales_order_directs_order_by_id_foreign` (`order_by_id`),
  KEY `sales_order_directs_store_id_foreign` (`store_id`),
  KEY `sales_order_directs_submitted_by_id_foreign` (`submitted_by_id`),
  KEY `sales_order_directs_transfer_to_account_id_foreign` (`transfer_to_account_id`),
  CONSTRAINT `sales_order_directs_delivery_location_id_foreign` FOREIGN KEY (`delivery_location_id`) REFERENCES `delivery_locations` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `sales_order_directs_delivery_service_id_foreign` FOREIGN KEY (`delivery_service_id`) REFERENCES `delivery_services` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `sales_order_directs_order_by_id_foreign` FOREIGN KEY (`order_by_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `sales_order_directs_store_id_foreign` FOREIGN KEY (`store_id`) REFERENCES `stores` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `sales_order_directs_submitted_by_id_foreign` FOREIGN KEY (`submitted_by_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `sales_order_directs_transfer_to_account_id_foreign` FOREIGN KEY (`transfer_to_account_id`) REFERENCES `transfer_to_accounts` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1076 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
